       .foregroundColor(.gold)                Text("Let this guide you today.")                    .font(.system(size: 18, design: .serif))                    .italic()                    .foregroundColor(Color.white.opacity(0.85))                    .padding(.top, 8)                Spacer()                Button(action: {                    // Navigate to the "Ask a Question" (Chat) tab                    selectedTab = 1                    // Dismiss this cover                    showVerse   = false                }) {                    Text("Ask a Question")                        .font(.system(size: 20, weight: .semibold))                        .frame(maxWidth: .infinity)                        .padding(.vertical, 16)                        .background(Color.gold)                        .foregroundColor(.white)                        .cornerRadius(30)                }                .padding(.horizontal, 32)                .padding(.bottom, 40)            }        }    }    /// Date formatter for "YYYY-MM-DD"    private static let dateFormatter: DateFormatter = {        let df = DateFormatter()        df.dateFormat = "yyyy-MM-dd"        return df    }()}struct BibleVerse: Identifiable {    let id = UUID()    let text: String    let reference: String}private let bibleVerses: [BibleVerse] = [    BibleVerse(text: """    Peace I leave with you; my peace I give to you. \    Not as the world gives do I give to you. \    Let not your hearts be troubled, neither let them be afraid.    """, reference: "John 14:27"),    BibleVerse(text: """    Fear not, for I have redeemed you; \    I have called you by name, you are mine.    """, reference: "Isaiah 43:1"),    BibleVerse(text: """    Trust in the Lord with all your heart, \    and do not lean on your own understanding.    """, reference: "Proverbs 3:5"),    BibleVerse(text: """    Come to me, all who labor and are heavy laden, \    and I will give you rest.   